UPDATE instituteconnect.workspace AS w SET data=w.data || jsonb_build_object('users', coalesce(w.data->'users', '[]'::jsonb) || coalesce((SELECT jsonb_agg(record) FROM jsonb_array_elements(s.payload->'users') AS record WHERE NOT EXISTS (SELECT 1 FROM jsonb_array_elements(coalesce(w.data->'users', '[]'::jsonb)) AS existing WHERE existing->>'id'=record->>'id')), '[]'::jsonb),
'institutions', coalesce(w.data->'institutions', '[]'::jsonb) || coalesce((SELECT jsonb_agg(record) FROM jsonb_array_elements(s.payload->'institutions') AS record WHERE NOT EXISTS (SELECT 1 FROM jsonb_array_elements(coalesce(w.data->'institutions', '[]'::jsonb)) AS existing WHERE existing->>'id'=record->>'id')), '[]'::jsonb),
'contacts', coalesce(w.data->'contacts', '[]'::jsonb) || coalesce((SELECT jsonb_agg(record) FROM jsonb_array_elements(s.payload->'contacts') AS record WHERE NOT EXISTS (SELECT 1 FROM jsonb_array_elements(coalesce(w.data->'contacts', '[]'::jsonb)) AS existing WHERE existing->>'id'=record->>'id')), '[]'::jsonb),
'events', coalesce(w.data->'events', '[]'::jsonb) || coalesce((SELECT jsonb_agg(record) FROM jsonb_array_elements(s.payload->'events') AS record WHERE NOT EXISTS (SELECT 1 FROM jsonb_array_elements(coalesce(w.data->'events', '[]'::jsonb)) AS existing WHERE existing->>'id'=record->>'id')), '[]'::jsonb),
'registrations', coalesce(w.data->'registrations', '[]'::jsonb) || coalesce((SELECT jsonb_agg(record) FROM jsonb_array_elements(s.payload->'registrations') AS record WHERE NOT EXISTS (SELECT 1 FROM jsonb_array_elements(coalesce(w.data->'registrations', '[]'::jsonb)) AS existing WHERE existing->>'id'=record->>'id')), '[]'::jsonb),
'participation', coalesce(w.data->'participation', '[]'::jsonb) || coalesce((SELECT jsonb_agg(record) FROM jsonb_array_elements(s.payload->'participation') AS record WHERE NOT EXISTS (SELECT 1 FROM jsonb_array_elements(coalesce(w.data->'participation', '[]'::jsonb)) AS existing WHERE existing->>'id'=record->>'id')), '[]'::jsonb),
'outcomes', coalesce(w.data->'outcomes', '[]'::jsonb) || coalesce((SELECT jsonb_agg(record) FROM jsonb_array_elements(s.payload->'outcomes') AS record WHERE NOT EXISTS (SELECT 1 FROM jsonb_array_elements(coalesce(w.data->'outcomes', '[]'::jsonb)) AS existing WHERE existing->>'id'=record->>'id')), '[]'::jsonb)),version=w.version+1,updated_at=now() FROM sample AS s WHERE w.id=true;
INSERT INTO instituteconnect.event_index(id,capacity,status) SELECT e->>'id',(e->>'capacity')::integer,e->>'status' FROM instituteconnect.workspace w CROSS JOIN LATERAL jsonb_array_elements(w.data->'events') AS e WHERE w.id=true AND e->>'id' LIKE 'SAMPLE-%' ON CONFLICT(id) DO NOTHING;
INSERT INTO instituteconnect.registration_index(id,event_id,user_id,status,recorded_at) SELECT r->>'id',r->>'eventId',r->>'userId',r->>'status',(r->>'date')::timestamptz FROM instituteconnect.workspace w CROSS JOIN LATERAL jsonb_array_elements(w.data->'registrations') AS r WHERE w.id=true AND r->>'id' LIKE 'SAMPLE-%' AND NOT EXISTS (SELECT 1 FROM instituteconnect.registration_index i WHERE i.id=r->>'id');
INSERT INTO instituteconnect.audit(id,actor_id,actor_name,message) VALUES('SAMPLE-SEED-v1','system','System','Added clearly labelled fictional sample institutions, contacts, events, registrations, attendance and outcomes. Existing records preserved; sample identities have no sign-in accounts.') ON CONFLICT(id) DO NOTHING;
